L000307	\section{Unraveling protocol}\label{App:unraveling}
L000308	
L000309	Our system with Hamiltonian
L000310	\begin{equation}
L000311	    H_{\text{S}} = - \sum_{\langle n,n'\rangle} J ( a^\dagger_n a^{}_{n'} + h.c. ) + \sum_nh_{\text{s}} a^\dagger_n a^{}_n,
L000312	\end{equation}
L000313	undergoes a dissipative dynamics where particles are created and destroyed with a rate $\gamma$:
L000314	
L000315	\begin{equation}\label{Eq:Lindblad}
L000316	    \dot\rho=-i[H_{\text{S}},\rho]+\gamma\sum_n(\mathcal{D}[a_n]\rho+\mathcal{D}[a_n^\dagger]\rho)
L000317	\end{equation}
L000318	
L000319	where $\mathcal{D}[L]\rho=L\rho L^\dagger-\frac{1}{2}\{L^\dagger L,\rho\}$.
L000320	
L000321	We want to unravel this dynamics in terms of quantum trajectories. To that end, we consider a stroboscopic dynamics, where the system evolves unitarily with $H_{\text{S}}$ for a time $dt=0.1$, after which the system is subject to an instantaneous quantum jump. The quantum jumps are described by the action of a set of Kraus operators $M_\mu$.
L000322	
L000323	\subsection{Unitary dynamics}
L000324	
L000325	During the unitary dynamics, the pure state of one quantum trajectory evolves as $\ket{\psi}\rightarrow e^{-iH\tau_u}\ket{\psi}$. The correlation matrix  $C_{ij}=\langle a_i^{\dagger}a_j\rangle$ evolves as $C_{ij}\rightarrow\bra{\psi}e^{iH\delta t}a_i^{\dagger}a_je^{-iH\delta t}\ket{\psi}=\sum_{i'j'}R_{ii'}^{\dagger}C_{i'j'}R_{j'j}$ where $R_{mn}$ is the matrix that describes the evolution operator. It can be found by diagonalizing the Hamiltonian in Fourier space, writing the evolution operator in such base and then transforming back to real space
L000326	
L000327	\begin{equation}
L000328	    R_{mn}=\frac1L\sum_{\mathbf k}e^{2\pi i(\mathbf{ m}-\mathbf{n})\cdot \mathbf{k}/L-i2J[\cos(2\pi k_x/L)+\cos(2\pi k_y/L)]\delta t}
L000329	\end{equation}
L000330	
L000331	In the limit $L\rightarrow\infty$, this can be written in terms of the Bessel functions~\cite{CoppolaCollura2022}, but for finite $L$ we can easily compute it numerically at a small computational cost.
L000332	
L000333	\subsection{Jump dynamics}
L000334	
L000335	At the end of each cycle of the unitary evolution, the system is subject to the quantum jumps part of the dynamics. The Kraus operators satisfy the normalization condition $\sum_\mu M^{\dagger}_\mu M_\mu=\mathbb1$ and lead to an update of the system wavefunction $\ket{\psi}\rightarrow\ket{\psi'}=\frac{M_\mu\ket{\psi}}{||M_\mu\ket{\psi}||}$ with probability given by the Born rule $||M_\mu\ket{\psi}||^2=\bra{\psi}M^{\dagger}_\mu M_\mu\ket{\psi}$.
L000336	
L000337	In our case the unraveling proceeds separately with distinct sets of Kraus operators associated to the loss or gain of particles: $\{M^+_{0,n}=\sqrt{1-p}+(1-\sqrt{1-p})\hat a_n^{\dagger}a_n, M^+_{1,n}=\sqrt{p}a_n^{\dagger}\}$ for the creation jump operators and $\{M^-_{0,n}=1-(1-\sqrt{1-p})\hat a_n^\dagger a_n, M^-_{1,n}=\sqrt{p}a_n\}$ for the destruction jump operators, where $p=\gamma\delta t$.
L000338	
L000339	The jump protocol is the following.
L000340	For the jump associated to $a_n^{\dagger}$:
L000341	\begin{itemize}
L000342	    \item With probability $p\langle a_na_n^{\dagger}\rangle$ the state is updated as $\ket{\psi}\rightarrow\ket{\psi}=\frac{a_n^{\dagger}\ket{\psi}}{\sqrt{\langle a_na_n^{\dagger}\rangle}}$.
L000343	    \item With probability $1-\delta p$ the state is updated as $\ket{\psi}\rightarrow\ket{\psi}=\frac{M^+_{0,n}\ket{\psi}}{\sqrt{1-\delta p}}$ where $\delta p=p\langle a_na_n^{\dagger}\rangle$.
L000344	\end{itemize}
L000345	
L000346	In terms of the correlation matrix: with probability $p(1-C_{nn})$ we apply $a_n^{\dagger}$ and find
L000347	\begin{equation}
L000348	    C_{ij} \rightarrow C_{ij}+\frac{(\delta_{in}-C_{in})(\delta_{nj}-C_{nj})}{1-C_{nn}}
L000349	\end{equation}
L000350	
L000351	With probability $1-\delta p=1-p(1-C_{nn})$ we apply $M^+_{0,n}$ and find
L000352	\begin{align}
L000353	C_{ij}\rightarrow C_{ij} &- \frac{p}{1-\delta p}C_{in}C_{nj} \\
L000354	                  \notag &+ \frac{C_{nn}\delta_{in}\delta_{nj}(1-\sqrt{1-p})^2}{1-\delta p} \\
L000355	                  \notag &+ \frac{\sqrt{1-p}(1-\sqrt{1-p})(\delta_{in}C_{nj}+C_{in}\delta_{nj})}{1-\delta p}
L000356	\end{align}
L000357	
L000358	For the jump associated with $a_n$:
L000359	\begin{itemize}
L000360	    \item With probability $p\langle a_n^{\dagger}a_n\rangle$ the state is updated as $\ket{\psi}\rightarrow\ket{\psi}=\frac{a_n\ket{\psi}}{\sqrt{\langle a_n^{\dagger}a_n\rangle}}$.
L000361	    \item With probability $1-\delta p$ the state is updated as $\ket{\psi}\rightarrow\ket{\psi}=\frac{M^-_{0,n}\ket{\psi}}{\sqrt{1-\delta p}}$ where $\delta p=p\langle a_n^{\dagger}a_n\rangle$.
L000362	\end{itemize}
L000363	
L000364	In terms of the correlation matrix, with probability $pC_{nn}$ we apply $a_n$ and find
L000365	\begin{equation}
L000366	C_{ij} \rightarrow C_{ij}-\frac{C_{in}C_{nj}}{C_{nn}}
L000367	\end{equation}
L000368	
L000369	With probability $1-\delta p=1-pC_{nn}$ we apply $M^-_{0,n}$ and find
L000370	\begin{align}
L000371	C_{ij}\rightarrow C_{ij} &+ \frac{p}{1-\delta p}C_{in}C_{nj} \\
L000372	                  \notag &+ \frac{C_{nn}\delta_{in}\delta_{nj}(1-\sqrt{1-p})^2}{1-\delta p} \\
L000373	                  \notag &- \frac{(1-\sqrt{1-p})(\delta_{in}C_{nj}+C_{in}\delta_{nj})}{1-\delta p}
L000374	\end{align}
L000375	
L000376	\section{Steady state of the system}
L000377	\begin{figure}[htbp!]
L000378	    \includegraphics[width=\linewidth]{A_Dynamics.png}
L000379	    \caption{The dynamics of $C^{\text{SS}}$ in the unitary-evolved $C_0$.
L000380	    (a) $\tilde{C}_{n,n}^{\text{SS}}$ quantifies the diagonal deviation from the infinite-temperature state.
L000381	    (b) $\tilde{C}_{n,n^\prime}^{\text{SS}}$ quantifies the off-diagonal deviation from the infinite-temperature state.
L000382	    (c) $\tilde{C}^{\text{SS}, \text{ME}}_{n, n^\prime}$ quantifies the difference between $C^{\text{SS}}$ and $C^{\text{ME}}$.
L000383	    In the steady-state, all three quantities are expected to diminish to $0$.
L000384	    The system size is $N=36$.}
L000385	    \label{fig:A_Dynamics}
L000386	\end{figure}
L000387	
L000388	In the unitary system-bath setup, the total correlation matrix is
L000389	\begin{equation}
L000390	    C_0 =
L000391	    \begin{bmatrix}
L000392	        C^{\text{SS}} & C^{\text{SB}} \\
L000393	        {C^{\text{SB}}}^\dagger & C^{\text{BB}} \\
L000394	    \end{bmatrix}
L000395	,\end{equation}
L000396	where $C^{\text{SS}}$ is the system correlation matrix, $C^{\text{BB}}$ is the bath correlation matrix, and $C^{\text{SB}}$ is the system-bath correlation matrix.
L000397	On the other hand, the GKSL master equation allows access to only the system correlation matrix $C^{\text{ME}}$.
L000398	At large time $t_{\text{s}} = 50/J$, both $C^{\text{SS}}$ and $C^{\text{ME}}$ converge to the infinite-temperature state, i.e., $C^{\text{SS}}(t_{\text{s}}) = C^{\text{ME}}(t_{\text{s}}) = \mathbb{1}/2$, where $\mathbb{1}$ is the identity matrix.
L000399	We show that the unitary evolution of $C_0$ under the full system-bath Hamiltonian (Eq.(3) of the main text) yields the infinite-temperature steady state $C^{\text{SS}}$.
L000400	For all unitary system-bath evolutions, we use $\omega_{\text{max}}=10J$, $h_s=5J$, and $M=100$.
L000401	Increasing $M$ further does not quantitatively change the results.
L000402	
L000403	At $t = 0$, $C^{\text{SS}}$ is initialized as a pure state with checkerboard occupation and $C^{\text{BB}}$ is initialized as an infinite-temperature mixed state.
L000404	We fixed the initial configuration of the system for ease of comparison between the two evolutions.
L000405	The steady-state is independent of the initial system configuration.
L000406	In Fig.~\ref{fig:A_Dynamics}(a) we plot the diagonal deviation from the infinite-temperature state $\tilde{C}_{n,n}^{\text{SS}} = \sum_{n} | C^{\text{SS}}_{n,n} - 1/2|^2$, and in Fig.~\ref{fig:A_Dynamics}(b) we show the off-diagonal deviation $\tilde{C}_{n,n^\prime}^{\text{SS}} = \sum_{n,n^\prime} | C^{\text{SS}}_{n,n^\prime\neq n} |^2$.
L000407	In the steady state, these quantities are expected to vanish for both $C^{\text{SS}}$ and $C^{\text{ME}}$.
L000408	In Fig.~\ref{fig:A_Dynamics}(c), we quantify the difference between $C^{\text{SS}}$ and $C^{\text{ME}}$ using $\tilde{C}^{\text{SS}, \text{ME}} = \sum_{n,n^\prime} | C^{\text{ME}}_{n, n^\prime} - C^{\text{SS}}_{n, n^\prime}|^2$.
L000409	At short times, the difference is non-negligible due to the finite system-bath coupling effects neglected by the master equation.
L000410	At longer time $t_{\text{s}} = 50/J$, the difference becomes $< 10^{-6}$ for all $\gamma$ values considered.
L000411	Hence, under the unitary evolution of the system-bath setup, the system converges to the expected infinite-temperature state $C^{\text{SS}}=\mathbb{1}/2$.
L000412	Note that none of these quantities is averaged over the system size. Thus, the error per site is even smaller.
L000413	
L000414	\section{Logarithmic Fermionic Negativity}\label{SM:LFN}
L000415	Given the total correlation matrix of the system-bath setup, $C$, we define $\Gamma = 2C - \mathbb{1}$.
L000416	For a bipartition of the total setup into left and right parts, $\Gamma$ is expressed as
L000417	\begin{equation}
L000418	    \Gamma =
L000419	    \begin{bmatrix}
L000420	        \Gamma^{LL} & \Gamma^{LR} \\
L000421	        {\Gamma^{LR}}^\dagger & \Gamma^{RR} \\
L000422	    \end{bmatrix} ,
L000423	\end{equation}
L000424	where each block corresponds to the correlations between the segments indicated in the superscript.
L000425	From $\Gamma$, we introduce the transformed matrices
L000426	\begin{equation}
L000427	    \Gamma_\pm =
L000428	    \begin{bmatrix}
L000429	        \Gamma^{LL} & \pm i \Gamma^{LR} \\
L000430	        \pm i {\Gamma^{LR}}^\dagger & -\Gamma^{RR} \\
L000431	    \end{bmatrix} ,
L000432	\end{equation}
L000433	and
L000434	\begin{equation}
L000435	    \Gamma_* = \frac{1}{2} \left[ 1 - (1 + \Gamma_+ \Gamma_-)^{-1} (\Gamma_+ + \Gamma_-) \right] .
L000436	\end{equation}
L000437	
L000438	Using these matrices, the logarithmic fermionic negativity is given by
L000439	\begin{equation} \label{eq:LFN}
L000440	    E(C) = \sum_j \left[ \ln \left( \sqrt{\mu_j} + \sqrt{1 - \mu_j} \right) + \frac{1}{2} \left( 1 - 2 \lambda_j + 2 \lambda_j^2 \right) \right],
L000441	\end{equation}
L000442	where $\mu_j$ and $\lambda_j$ are the eigenvalues of $\Gamma_*$ and $C$ respectively.
L000443	
L000444	From Eq.~(\ref{eq:LFN}), we see that the calculation of the logarithmic fermionic negativity involves the diagonalization of the total correlation matrix $C$, regardless of the size of the bipartition we are interested in studying.
L000445	This is in contrast to the von Neumann entropy, which only requires the diagonalization of the correlation matrix of the partition of interest.
L000446	
L000447	\section{Time Evolution of Various Observables}
L000448	\begin{figure}[htbp!]
L000449	    \includegraphics[width=\linewidth]{A_Tevo.png}
L000450	    \caption{Time evolution of the entanglement related observables (a) $\mathcal{E}(t)$, (b) $\mathcal{I}(t)$, and (c) $\mathcal{C}(t)$.
L000451	    }
L000452	    \label{fig:A_Tevo}
L000453	\end{figure}
L000454	
L000455	In Fig.~\ref{fig:A_Tevo}, we show the time evolution of the entanglement-related observables, (a) $\mathcal{E}(t)$, (b) $\mathcal{I}(t)$, and (c) $\mathcal{C}(t)$ in the unitary system-bath setup.
L000456	All three observables reach their steady-state values before $t_{\text{s}} = 50/J$.
L000457	The simulation parameters used are the same as in Fig.~\ref{fig:A_Dynamics}.
L000458	
L000459	\begin{figure}[htbp!]
L000460	    \includegraphics[width=\linewidth]{A_off_diag.png}
L000461	    \caption{Time evolution of the connected correlation weight between (a) the left and right partitions, $\mathcal{C}$, (b) the left and right system, $\mathcal{C}^{\text{SS}}$, (c) between the left system and right baths, $\mathcal{C}^{\text{SB}}$, and (d) between the left and right baths, $\mathcal{C}^{\text{BB}}$.
L000462	    }
L000463	    \label{fig:A_off_diag}
L000464	\end{figure}
L000465	
L000466	In Fig.~\ref{fig:A_off_diag}, we plot the connected correlation weight between (a) the left and right partitions, $\mathcal{C} = \sum_{(n,m),(n^\prime,m^\prime)} \left| C^{\text{LR}}_{(n,m),(n^\prime,m^\prime)} \right|^2$, (b) the left and right system, $\mathcal{C}^{\text{SS}} = \sum_{i \in L, i^\prime \in R} | C^{\text{SS}}_{i,i^\prime} |^2$, (c) between the left system and right baths, $\mathcal{C}^{\text{SB}} = \sum_{i \in L, i^\prime \in R, m} | C^{\text{SB}}_{i, (i^\prime, m)} |^2$, and (d) between the left and right baths, $\mathcal{C}^{\text{BB}} = \sum_{i \in L, m, i^\prime \in R, m^\prime} | C^{\text{BB}}_{(i,m), (i^\prime, m^\prime)} |^2$.
L000467	These quantities provide information on the entangling structure between different parts of the system-bath setup.
L000468	At $t \gtrsim t_{\text{s}}$, both $\mathcal{C}^{\text{SS}}$ and $\mathcal{C}^{\text{SB}}$ becomes negligible.
L000469	The correlations in $\mathcal{C}$ are mostly contributed by $\mathcal{C}^{\text{BB}}$, indicating that the entanglement between the left and right partitions originates entirely from bath-bath correlations.
L000470	
L000471	\section{Unitary Evolution with Random Pure-State Baths}
L000472	\begin{figure}[htbp!]
L000473	    \includegraphics[width=\linewidth]{A_U_traj.png}
L000474	    \caption{Time evolution of the system-system correlation matrix $\overline{C^{\text{SS}}}$ in $\overline{C_0}$.
L000475	    (a) $\tilde{C}_{n,n}^{\text{SS}}$ quantifies the deviation of system densities from the infinite-temperature state.
L000476	    (b) $\tilde{C}_{n,n^\prime}^{\text{SS}}$ quantifies the deviation of the system correlations from the infinite-temperature state.
L000477	    (c) $\tilde{C}^{\text{SS}, \rm{ME}}_{n, n^\prime}$ quantifies the deviation of $\overline{C^{\text{SS}}}$ from $C^\text{ME}$ predicted by the GKSL master equation.
L000478	    The system size is $N=36$.}
L000479	    \label{fig:A_U_traj}
L000480	\end{figure}
L000481	
L000482	In this section, we show that the correct system correlation matrix can also be recovered from our unitary setup with baths initialized randomly in pure states.
L000483	Using the $H_{\text{tot}}$ (Eq.(3) of the main text), we evolve the total correlation matrix $C_0$ and compute the averaged $\overline{C_0}$ over $N_{\text{init}}$ different pure-state bath initializations.
L000484	In Fig.~\ref{fig:A_U_traj}(a) we plot the diagonal deviation from the infinite-temperature state $\tilde{C}_{n,n}^{\text{SS}} = \sum_{n} | \overline{C^{\text{SS}}_{n,n}} - 1/2|^2$.
L000485	In Fig.~\ref{fig:A_U_traj}(b) we show the off-diagonal deviation $\tilde{C}_{n,n^\prime}^{\text{SS}} = \sum_{n,n^\prime} | \overline{C^{\text{SS}}_{n,n^\prime\neq n}} |^2$.
L000486	In Fig.~\ref{fig:A_U_traj}(c) we compute the distance between $\overline{C^{\text{SS}}}$ obtained from the unitary evolution, and $C^{\text{ME}}$ obtained from the master equation (Eq.(2) of the main text), $\tilde{C}^{\text{SS}, \text{ME}}_{n, n^\prime} = \sum_{n,n^\prime} | C^{\text{SS}, \text{ME}}_{n, n^\prime} - \overline{C^{\text{SS}}_{n, n^\prime}}|^2$.
L000487	The deviation from the infinite-temperature state decreases as $N_{\text{init}}$ increases.
L000488	With $N_{\text{init}} = 256$, for example, $\overline{C^{\text{SS}}_{n, n}}/ \overline{C^{\text{SS}}_{n, n^\prime \neq n}} \approx 5 \times 10^2$ at $t=t_{\text{s}}$.
